import base64,hashlib,json,os,re,subprocess,sys
from pathlib import Path
from datetime import UTC,datetime
state={'at':datetime.now(UTC).isoformat(),'http':[],'checks':[],'errors':[]}
def sha(data):return hashlib.sha256(data).hexdigest()
def check(value,label):
    state['checks'].append({'check':label,'passed':bool(value)})
    if not value:raise RuntimeError(label)
try:
    names=['socai2-investigation-api','socai2-api-1','socai2-agents-1','socai2-litellm-1']
    containers=json.loads(subprocess.check_output(['docker','inspect',*names]))
    state['containers']={c['Name'].lstrip('/'):{'id':c['Id'],'image':c['Image'],'started_at':c['State']['StartedAt'],'running':c['State']['Running']} for c in containers}
    check(state['containers']['socai2-investigation-api']['image']=='sha256:17cac869d789fae8109cd04a686dc4c6f8d662a27195f9a7cb9b9ab0a0941de9','online_is_r12')
    check(all(c['running'] for c in state['containers'].values()),'containers_running')
    state['profile_sha256']=sha(Path('/opt/sting-aisoc-socai2/private/investigation-v2.env').read_bytes())
    keys=Path('/opt/sting-aisoc-socai2/private/investigation-dev-keys.json')
    check(keys.stat().st_mode & 0o777==0o600,'credential_file_mode')
    tokens=json.loads(keys.read_text())
    client='/opt/sting-aisoc-socai2/investigation-v2/20261101-r11/scripts/investigation_client.py'
    def get(tenant,path,label,expected=200):
        response=subprocess.run([sys.executable,'-B',client,'GET',path,'--timeout','20'],capture_output=True,timeout=30,env={**os.environ,'AISOC_API_TOKEN':tokens[tenant]})
        match=re.search(rb'HTTP (\d+)',response.stderr);status=int(match.group(1)) if match else None
        state['http'].append({'label':label,'method':'GET','tenant_id':tenant,'path':path,'status':status,'response_sha256':sha(response.stdout),'response_base64':base64.b64encode(response.stdout).decode()})
        check(status==expected,label+':status')
        return json.loads(response.stdout) if expected==200 and not label.endswith('-report') else response.stdout
    for step in PLAN['cases']:
        tenant=step['tenant_id']; case_path='/api/v1/cases/'+step['case_id']
        readback=step['path'].removesuffix('/investigate')+'/investigations/'+step['planned_run_id']
        if step['label']=='C':continue
        baseline=BASELINES[step['label']]
        case=get(tenant,case_path,step['label']+'-case')
        check(set(baseline['selected_member_ids']).issubset(case['alert_ids']),step['label']+':selected_members')
        desc=case.get('description'); check((sha(desc.encode()) if desc is not None else None)==baseline['case_description']['sha256'],step['label']+':case_description')
        for item in baseline['alerts']:
            alert=get(tenant,'/api/v1/alerts/'+item['alert_id'],step['label']+'-'+item['evidence_id'])
            for field,saved in item['source_fields'].items():
                value=alert.get(field)
                raw=json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode() if field=='raw_event' and value is not None else value.encode() if value is not None else None
                check((sha(raw) if raw is not None else None)==saved['sha256'],step['label']+':'+item['evidence_id']+':'+field)
            check(alert.get('source_event_ids')==item['source_event_ids'],step['label']+':'+item['evidence_id']+':source_events')
        old_run='22b48b78-3716-5a64-994f-788d020dc760' if step['label']=='A' else '4f094ed4-b4f9-5db9-8cc2-b5f8c781858e'
        old_path=step['path'].removesuffix('/investigate')+'/investigations/'+old_run
        result=get(tenant,old_path,step['label']+'-old-result')
        check(result['report_url'].startswith(old_path+'/'),step['label']+':old_report_path')
        get(tenant,result['report_url'],step['label']+'-old-report')
except Exception as exc:state['errors'].append({'type':type(exc).__name__,'message':str(exc)})
print(json.dumps(state,ensure_ascii=False))
